#pragma material(ShadingModel = Unlit, Backend = Graph)

uniform float Mask = 0.6;

export void M_RtBranches(inout material m)
{
    float3 Colour = float3(0.0, 0.0, 1.0);
    float3 Colour_2 = float3(1.0, 0.0, 0.0);

    m.EmissiveColor = Mask > 0.5 ? Colour_2 : Colour;
}

#pragma layout(Node, Var = Colour, X = 18, Y = -620)
#pragma layout(Node, Var = Colour_2, X = 18, Y = 76)
#pragma layout(Node, Var = Mask, X = 0, Y = -256)
